'use client';
import {useCallback,useEffect,useId,useMemo,useRef,useState,type FormEvent} from 'react';
import {getSupabaseBrowserClient} from '../../../lib/supabase/browser';
import {EXCLUSION_LABELS,centerPixelLabel,imageDataUrl,METHODS,METHOD_LABELS,percent,REASONS,STATE_LABELS,summarize,tokyo,type Evaluation,type GroundReport,type Health,type ImageRow,type LabData,type Shadow} from '../../../lib/research/rainLab';
import {LabAccessError,loadCaseImages,loadLab,saveGround} from '../../../lib/research/rainLabRepository';
import s from './lab.module.css';
import {explainCase,PATTERNS,VERDICT_LABELS} from '../../../lib/research/rainMismatch';
const jma=(value:string|null)=>{if(!value)return '';if(/^\d{14}$/.test(value))return value;const d=new Date(value);return Number.isFinite(d.getTime())?d.toISOString().replace(/[-:TZ.]/g,'').slice(0,14):'';};
const EVENT_LABELS:Record<string,string>={RAIN_ENDING:'止むよ',RAIN_APPROACHING:'降るよ',ACTIONABLE_RAIN_APPROACHING:'降るよ'};
const FEEDBACK:Record<string,string>={RAINED:'降った',DID_NOT_RAIN:'降らなかった',ALREADY_RAINING:'すでに降っていた',STOPPED:'止んだ',DID_NOT_STOP:'止まなかった',ALREADY_DRY:'すでに降っていなかった',UNKNOWN:'わからない'};
function Crop({image,location,title}:{image:ImageRow|null;location:{latitude:number;longitude:number};title:string}){
 const patternId=useId().replace(/:/g,'');const [dark,setDark]=useState(false);
 const url=image?imageDataUrl(image.crop_png):null,w=image?.metadata.window;
 const worldX=(location.longitude+180)/360*262144,worldY=(1-Math.asinh(Math.tan(location.latitude*Math.PI/180))/Math.PI)/2*262144;
 const masks=image?.availability_mask.slice(2).match(/../g)??[];
 return <figure className={s.figure}><figcaption>{title}</figcaption>{image&&url&&w?<><div className={s.crop} style={dark?{backgroundColor:'#263d50',backgroundImage:'none'}:undefined}>
  {/* Raw PNG pixels, not a resampled weather prediction. */}<img src={url} alt={`${title} ${tokyo(image.valid_time)}の雨量画像`} />
  <svg viewBox={`0 0 ${image.width} ${image.height}`} aria-hidden='true'><defs><pattern id={`missing-${patternId}`} width='0.6' height='0.6' patternUnits='userSpaceOnUse'><path d='M0 0L.6 .6' stroke='#c12d6b' strokeWidth='.12'/></pattern></defs>
   {masks.map((v,i)=>v==='00'?<rect key={i} x={i%image.width} y={Math.floor(i/image.width)} width='1' height='1' fill={`url(#missing-${patternId})`}/>:null)}
   {[250,500,1000].map((r,i)=><circle key={r} cx={worldX-w.originX} cy={worldY-w.originY} r={r/w.metersPerPixel} fill='none' stroke={['#159786','#3476c4','#c58a2a'][i]} strokeWidth='1.2' vectorEffect='non-scaling-stroke'/>)}
   <path d={`M${worldX-w.originX-.6} ${worldY-w.originY}h1.2M${worldX-w.originX} ${worldY-w.originY-.6}v1.2`} stroke='#c63c54' strokeWidth='1.6' vectorEffect='non-scaling-stroke'/>
  </svg></div><button type='button' className={s.contrast} aria-pressed={dark} onClick={()=>setDark(!dark)}>{dark?'市松背景に戻す':'淡い雨色を暗い背景で見る'}</button><div className={s.muted}>対象 {tokyo(image.valid_time)}</div><div className={s.notes}>中心：{centerPixelLabel(image,(Math.floor(worldY)-w.originY)*image.width+Math.floor(worldX)-w.originX)}<br/>RGBA {image.metadata.centerRgba?['r','g','b','a'].map(k=>image.metadata.centerRgba![k as 'r'|'g'|'b'|'a']).join(', '):'未取得'}</div><div className={s.notes}>発表 {tokyo(image.base_time)}<br/>取得 {tokyo(image.metadata.capturedAt)}<br/>{image.complete?'全画素取得':'欠けた画素あり'}{image.frame_kind==='FORECAST'?image.metadata.matchesInputPixel===true?' · 当時の中心と一致':' · 入力中心は未確認':''}</div>{image.frame_kind==='FORECAST'?<p className={s.notes}>同じ発表・対象時刻・地点のURLから後で回収した画像です。中心画素の一致は、通知時の画像全体が同一だった証明にはなりません。当時の画像全体のハッシュは未保存です。</p>:null}</>:<div className={s.noImage}>この時刻の画像は未保存です<br/>保存対象外・未回収を含みます</div>}</figure>;
}
function GroundForm({evaluation,onSaved}:{evaluation:Evaluation;onSaved:()=>Promise<void>}){
 const [weather,setWeather]=useState<GroundReport['weather']|''>(''),[time,setTime]=useState(''),[source,setSource]=useState<GroundReport['report_source']>('AT_LOCATION'),[confirmed,setConfirmed]=useState(false),[note,setNote]=useState(''),[busy,setBusy]=useState(false),[message,setMessage]=useState(''),[success,setSuccess]=useState(false);
 const submit=async(event:FormEvent)=>{event.preventDefault();setSuccess(false);setMessage('');if(!weather||!time){setMessage('天気と実際に確認した時刻を入力してください。');return;}setBusy(true);try{await saveGround(getSupabaseBrowserClient(),{evaluation_id:evaluation.id,observed_at:new Date(time).toISOString(),weather,report_source:source,location_confirmed:confirmed,note});setSuccess(true);setMessage('開発用の観測を保存しました。一般向け履歴の回答は変更していません。');await onSaved();}catch{setMessage('保存できませんでした。確認時刻・地点の確認・閲覧権限を確認してください。');}finally{setBusy(false);}};
 const now=()=>{const d=new Date(),local=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);setTime(local);};
 return <form className={s.form} onSubmit={event=>void submit(event)}><h3>現地の参考情報を記録（任意）</h3><p className={s.muted}>現地にいた場合だけ、確認できた事実を任意で記録してください。入力しなくても自動評価は進みます。近隣情報も参考として保存します。</p>
  <div className={s.formGrid}><label className={s.label}>実際の天気<select value={weather} onChange={e=>setWeather(e.target.value as typeof weather)} required><option value=''>選んでください</option><option value='RAIN'>雨が降っていた</option><option value='NO_RAIN'>雨は降っていなかった</option><option value='UNKNOWN'>確認できない</option></select></label>
   <label className={s.label}>確認方法<select value={source} onChange={e=>{setSource(e.target.value as typeof source);setConfirmed(false);}}><option value='AT_LOCATION'>登録地点そのもので確認</option><option value='CAMERA'>登録地点のカメラで確認</option><option value='NEARBY_REFERENCE'>近隣の情報・雨量計など（参考）</option></select></label>
   <label className={s.label}>実際に確認した時刻<input type='datetime-local' value={time} onChange={e=>setTime(e.target.value)} required/></label><div><button type='button' onClick={now}>いまの時刻を入力</button></div></div>
  {source!=='NEARBY_REFERENCE'?<label className={s.check}><input type='checkbox' checked={confirmed} onChange={e=>setConfirmed(e.target.checked)} required/>登録地点そのものと、入力した時刻の天気を確認しました</label>:<p className={s.notes}>近隣の情報は、登録地点の正解として一致率に使いません。</p>}
  <label className={s.label}>メモ（任意・300文字まで）<textarea maxLength={300} value={note} onChange={e=>setNote(e.target.value)}/></label><p className={s.notes}>同じケース・同じ時刻の再保存は訂正になります。現地報告がない場合や報告同士が食い違う場合でも、レーダーによる自動評価は保留にしません。</p>
  <button disabled={busy} type='submit'>{busy?'保存中…':'開発用の観測を保存'}</button>{message?<p role='status' className={success?s.success:s.error}>{message}</p>:null}</form>;
}
function CaseCard({evaluation,shadow,label,reports,feedback,threshold,onSaved}:{evaluation:Evaluation;shadow:Shadow|undefined;label:string;reports:GroundReport[];feedback:LabData['feedback'][number]|undefined;threshold:number;onSaved:()=>Promise<void>}){
 const [images,setImages]=useState<ImageRow[]|null>(null),[loading,setLoading]=useState(false),[error,setError]=useState(''),[selectedTime,setSelectedTime]=useState(jma(evaluation.target_time)),[base,setBase]=useState(shadow?.comparison.groups[0]?.baseTime??'');const request=useRef(0);
 useEffect(()=>()=>{request.current++;},[]);
 const load=async()=>{const rid=++request.current;setLoading(true);setError('');try{const rows=await loadCaseImages(getSupabaseBrowserClient(),evaluation.id);if(rid===request.current)setImages(rows);}catch{if(rid===request.current)setError('画像を取得できません。権限と接続を確認してください。');}finally{if(rid===request.current)setLoading(false);}};
 const group=shadow?.comparison.groups.find(g=>g.baseTime===base)??shadow?.comparison.groups[0],variant=group?.variants.find(v=>Math.abs(v.threshold-threshold)<.0001);
 const times=[...new Set([selectedTime,...(images??[]).filter(i=>i.frame_kind!=='INPUT_OBSERVATION').map(i=>i.valid_time),...(group?.point.series??[]).map(f=>f.validTime)].filter(Boolean))].sort();
 const forecast=images?.find(i=>i.frame_kind==='FORECAST'&&i.valid_time===selectedTime&&(!group||i.base_time===group.baseTime))??null,observation=images?.find(i=>i.frame_kind==='OBSERVATION'&&i.valid_time===selectedTime)??null;
 const observationFeature=shadow?.features.find(f=>f.kind==='OBSERVATION'&&f.validTime===selectedTime);
 const feature=shadow?.features.find(f=>f.kind==='FORECAST'&&f.validTime===selectedTime&&(!group||f.baseTime===group.baseTime));
 const explanations=explainCase(evaluation,shadow,selectedTime,group?.baseTime,threshold,reports);
 const candidates={point:group?.point.series.find(f=>f.validTime===selectedTime),area:variant?.area.series.find(f=>f.validTime===selectedTime),combined:variant?.combined.series.find(f=>f.validTime===selectedTime)};
 return <details className={s.case} onToggle={event=>{if(event.currentTarget.open&&images===null&&!loading)void load();}}><summary><span><strong>{label} · {EVENT_LABELS[evaluation.event_type]??'雨通知'}</strong><br/><span className={s.muted}>{tokyo(evaluation.created_at)} 通知 · 予測対象 {tokyo(evaluation.target_time)}</span></span><span className={s.pill}>{evaluation.shadow_state==='PENDING'?'比較の処理待ち':'比較結果あり'}</span></summary>
 <div className={s.caseBody}><p>{evaluation.snapshot.body}</p><span className={s.tag}>実況 {evaluation.state==='PENDING'?'回収中':evaluation.state==='COMPLETE'?'照合済み':'一部確認できず'}</span><span className={s.tag}>画像 {evaluation.image_state==='COMPLETE'?'保存済み':evaluation.image_state==='PENDING'?'回収中':'一部未取得'}</span>
 <div className={s.notes}>処理回数：実況 {evaluation.attempts??'—'} / 画像 {evaluation.image_attempts??'—'} / 比較 {evaluation.shadow_attempts??'—'}（初回を含むclaim回数）<br/>実況締切 {tokyo(evaluation.deadline_at)} · 画像は締切＋10分または60回、比較は締切＋20分または24回が通常処理の終了目安です。例外が続く場合や容量制限時の停止は別途監査が必要です。<br/>実況で未回収の時刻：{evaluation.radar_result?.missingTimes?.length?evaluation.radar_result.missingTimes.map(tokyo).join('、'):'なし／まだ未集計'}{evaluation.last_error||evaluation.image_error||evaluation.shadow_error?<><br/>取得・処理エラーあり。正常終了の記録とは分けて確認してください。</>:null}</div>
 <div className={s.filters}><label className={s.label}>比較する時刻<select value={selectedTime} onChange={e=>setSelectedTime(e.target.value)}>{times.map(t=><option key={t} value={t}>{tokyo(t)}</option>)}</select></label>{(shadow?.comparison.groups.length??0)>1?<label className={s.label}>予測の発表時刻<select value={group?.baseTime} onChange={e=>setBase(e.target.value)}>{shadow?.comparison.groups.map(g=><option key={g.baseTime} value={g.baseTime}>{tokyo(g.baseTime)}</option>)}</select></label>:null}<button type='button' disabled={loading} onClick={()=>void load()}>{loading?'画像を読込中…':'画像を更新'}</button></div>
 {error?<p className={s.error}>{error}</p>:null}<div className={s.images}><Crop image={forecast} location={evaluation.snapshot.location} title='当時の予測（後から回収）'/><Crop image={observation} location={evaluation.snapshot.location} title='対象時刻の実況'/></div>
 <div className={s.legend}><span style={{color:'#159786'}}>○ 250m</span><span style={{color:'#3476c4'}}>○ 500m</span><span style={{color:'#a16a19'}}>○ 1km</span><span>＋ 登録地点</span><span>市松＝取得済み透明（雨色なし） · 斜線＝未取得 · ほぼ白色も弱い雨</span></div>
 <section className={s.explanation}><h3>予報とレーダーの比較結果</h3><p className={s.notes}>画像の対象 {tokyo(selectedTime)}。時刻のずれは通知対象 {tokyo(evaluation.target_time)} を基準に確認します。レーダー上の差を表示します。現地報告は任意の参考情報であり、判定には使用しません。</p><p className={s.notes}>自動評価（雨色への遷移）：ぴったり {VERDICT_LABELS[evaluation.radar_result?.exact??'']??'未評価'} ／ ±5分 {VERDICT_LABELS[evaluation.radar_result?.within5??'']??'未評価'} ／ ±10分 {VERDICT_LABELS[evaluation.radar_result?.within10??'']??'未評価'}{evaluation.state==='PENDING'?'（処理中の暫定値）':''}</p>{explanations.length?<ul className={s.reasonList}>{explanations.map((x,i)=><li key={`${x.code}-${i}`} className={x.kind==='difference'?s.difference:s.hold}><strong>{x.kind==='difference'?'差あり':x.kind==='hold'?'データ確認が必要':'補足'}：{x.title}</strong><p>{x.detail}</p></li>)}</ul>:<p>この時刻の取得済みデータから、表示対象の不一致は検出されていません。地上の精度保証ではありません。</p>}</section>
 <div className={s.tableWrap}><table className={s.table}><thead><tr><th>方式</th><th>この時刻の候補</th><th>判定の根拠・保留理由</th></tr></thead><tbody>{METHODS.map(m=><tr key={m}><td className={s.method}>{METHOD_LABELS[m]}</td><td>{STATE_LABELS[candidates[m]?.state??'INDETERMINATE']}</td><td>{REASONS[candidates[m]?.reason??(m==='point'?'POINT_INPUT':'IMAGE_MISSING')]??'未確認'}</td></tr>)}</tbody></table></div>
 {[{name:'予測の面積内訳',feature},{name:'実況の面積内訳',feature:observationFeature}].map(({name,feature})=>feature?<div className={s.tableWrap} key={name}><table className={s.table}><caption>{name}</caption><thead><tr><th>範囲</th><th>雨域占有率</th><th>分類可能</th><th>欠測 / 未知色</th><th>中心の穴</th></tr></thead><tbody>{[250,500,1000].map(r=>{const c=feature.metrics.circles[String(r)];return c?<tr key={r}><td>{r===1000?'1km':`${r}m`}</td><td>{percent(c.rainFraction)}</td><td>{percent(c.usableCoverage)}</td><td>{percent(c.missingFraction)} / {percent(c.unknownFraction)}</td><td>{c.centerDryHoleM2===null?'—':`${Math.round(c.centerDryHoleM2).toLocaleString()}m²`}</td></tr>:null;})}</tbody></table></div>:<p className={s.notes} key={name}>{name}：画像の解析待ちです。</p>)}
 <p className={s.notes}>透明は取得できた画素で雨色がない状態です。未取得や、パレットにない未知色とは分けます。地上の無降雨を証明するものではありません。</p>
 <p className={s.notes}>占有率は「範囲の何％に雨色があるか」で、地点の降雨確率ではありません。表示用画素数も、独立したレーダー観測数ではありません。</p>
 {feedback?<p className={s.report}>一般向け履歴の回答：{FEEDBACK[feedback.actual_weather]??feedback.actual_weather} · 確認時刻 {tokyo(feedback.observed_at)}<br/>この回答は補助表示です。下の地点確認とは別に扱います。</p>:null}
 {reports.map(r=><p className={s.report} key={r.observed_at}>現地の参考報告 {tokyo(r.observed_at)}：{r.weather==='UNKNOWN'?'未確認':STATE_LABELS[r.weather]} · {r.report_source==='AT_LOCATION'?'現地':r.report_source==='CAMERA'?'地点カメラ':'近隣の参考情報'}{r.note?` · ${r.note}`:''}</p>)}
 <GroundForm evaluation={evaluation} onSaved={onSaved}/></div></details>;
}
function HealthCard({label,value,maxMinutes}:{label:string;value:Health|null;maxMinutes:number}){const age=value?(Date.now()-Date.parse(value.started_at))/60000:Infinity,ok=value?.status==='OK'&&age<=maxMinutes;return <div className={s.healthItem}><span className={`${s.dot} ${ok?'':s.dotWarn}`}/><strong>{label}</strong><div className={s.muted}>{!value?'記録なし':ok?'正常':value.status==='RUNNING'?'処理中':value.status==='UNKNOWN'?'雨情報を確認できず':age>maxMinutes?'更新が遅れています':'要確認'}</div><div className={s.notes}>{value?tokyo(value.started_at):'—'}</div></div>;}
export default function RainLab(){
 const [data,setData]=useState<LabData|null>(null),[gate,setGate]=useState<'checking'|'session'|'forbidden'|'error'|'ready'>('checking'),[message,setMessage]=useState(''),[busy,setBusy]=useState(false),[days,setDays]=useState(7),[target,setTarget]=useState('all'),[eventType,setEventType]=useState('all'),[threshold,setThreshold]=useState(.4),[updated,setUpdated]=useState<string|null>(null);const request=useRef(0);
 const refresh=useCallback(async()=>{const rid=++request.current;setBusy(true);setMessage('');try{const loaded=await loadLab(getSupabaseBrowserClient(),days);if(rid!==request.current)return;setData(loaded);setGate('ready');setUpdated(new Date().toISOString());}catch(error){if(rid!==request.current)return;setData(null);if(error instanceof LabAccessError)setGate(error.reason==='SESSION'?'session':'forbidden');else{setGate('error');setMessage('データを取得できません。接続を確認して再読込してください。');}}finally{if(rid===request.current)setBusy(false);}},[days]);
 useEffect(()=>{let timer:ReturnType<typeof setTimeout>|undefined;const invalidate=()=>{request.current++;setData(null);setGate('checking');if(timer)clearTimeout(timer);timer=setTimeout(()=>void refresh(),0);};let unsubscribe=()=>{};try{const sub=getSupabaseBrowserClient().auth.onAuthStateChange(invalidate);unsubscribe=()=>sub.data.subscription.unsubscribe();}catch{}
  const visible=()=>{if(document.visibilityState==='visible')void refresh();};void refresh();const poll=setInterval(visible,60000);document.addEventListener('visibilitychange',visible);window.addEventListener('pageshow',visible);return()=>{request.current++;if(timer)clearTimeout(timer);clearInterval(poll);unsubscribe();document.removeEventListener('visibilitychange',visible);window.removeEventListener('pageshow',visible);};
 },[refresh]);
 const filtered=useMemo(()=>data?{...data,evaluations:data.evaluations.filter(e=>(target==='all'||e.target_id===target)&&(eventType==='all'||(eventType==='ending'?e.event_type==='RAIN_ENDING':e.event_type!=='RAIN_ENDING')))}:null,[data,target,eventType]);
 const summary=useMemo(()=>filtered?summarize(filtered,threshold,'radar'):null,[filtered,threshold]);
 if(gate!=='ready'||!data||!filtered||!summary)return <main className={s.shell}><div className={s.gate}><div className={s.eyebrow}>DEVELOPER ONLY</div><h1>雨の判定ラボ</h1><p>{gate==='checking'?'閲覧権限を確認しています…':gate==='session'?'通知を受け取っている、いつものPWA・アカウントで開いてください。':gate==='forbidden'?'このアカウントは開発用画面の閲覧を許可されていません。':message}</p><p className={s.muted}>比較データは、許可された開発者の登録地点だけに限定しています。URLだけでは閲覧できません。</p><button onClick={()=>void refresh()} disabled={busy}>再確認</button> <a href='/'>いつもの画面へ</a></div></main>;
 const patternCases=new Map<string,Set<string>>();for(const e of filtered.evaluations){const sh=data.shadows.find(x=>x.evaluation_id===e.id);for(const reason of explainCase(e,sh,jma(e.target_time),sh?.comparison.groups[0]?.baseTime,threshold,data.reports)){const ids=patternCases.get(reason.code)??new Set<string>();ids.add(e.id);patternCases.set(reason.code,ids);}}
 const count=filtered.evaluations.length,reported=new Set(filtered.reports.filter(r=>r.location_confirmed&&r.report_source!=='NEARBY_REFERENCE'&&r.weather!=='UNKNOWN'&&filtered.evaluations.some(e=>e.id===r.evaluation_id)).map(r=>r.evaluation_id)).size;
 return <main className={s.shell}><div className={s.wrap}><header className={s.top}><div className={s.eyebrow}>AMEFURU / DEVELOPER LAB</div><div className={s.links}><a href='/'>通常画面へ</a><button onClick={()=>void refresh()} disabled={busy}>{busy?'更新中…':'更新'}</button></div></header>
 <h1 className={s.heading}>雨の判定ラボ</h1><p className={s.muted}>点・面・併用を、同じ予測時刻と同じ確認記録で比べる。<br/>開発者専用 · 通知は従来の判定で稼働中 · 更新 {tokyo(updated)}</p>
 <section className={s.banner} aria-live='polite'><h2>{!count?'まだ採用判断はできません':summary.paired?'レーダー実況との比較結果があります':'レーダー実況との比較を待っています'}</h2><p>{!count?'新しい通知が出ると、予測・実況画像と比較結果がここに蓄積されます。':summary.paired?'下の共通サンプルで予測と実況の差を確認できます。レーダー上の一致は地上での降

